using Bunit;
using Habitica.Application.Workspace;
using Habitica.Domain.Workspace;
using Habitica.WebApp.Components;
using Habitica.WebApp.State;
using Microsoft.Extensions.DependencyInjection;
using MudBlazor.Services;

namespace Habitica.WebApp.Tests.Workspace;

public sealed class TodoRecurringEditorTests:BunitContext
{
    private static readonly DateTimeOffset Now=new(2026,3,29,22,30,0,TimeSpan.Zero);
    private static CompanionTask Daily(string name="Native Daily")=>new(Guid.NewGuid(),1,name,CompanionTaskKind.Daily,CompanionTaskState.Active,CompanionPriority.Normal,Now,Now);
    private static RecurrenceRule Rule=>new(RecurrenceFrequency.Daily,1,new(2026,3,1),"Europe/Paris",[],[]);
    private sealed class Clock:TimeProvider {public override DateTimeOffset GetUtcNow()=>Now;public override TimeZoneInfo LocalTimeZone=>TimeZoneInfo.Utc;}
    private async Task<TodoOrganizationFixture> Setup(WorkspaceDocument document,bool cloud=true)
    {
        JSInterop.Mode=JSRuntimeMode.Loose;Services.AddMudServices();var f=new TodoOrganizationFixture();await f.Load(cloud,document);Services.AddSingleton<IAppSessionController>(f.Task.Session);Services.AddSingleton<IWorkspaceCloudClient>(f.Task.Client);Services.AddSingleton(f.Task.Database);Services.AddSingleton(f.Task.Controller);Services.AddSingleton(f.Organization);Services.AddSingleton(f.Todo);Services.AddSingleton<TodoTaskDraftStore>();Services.AddSingleton<TimeProvider>(new Clock());return f;
    }
    private static void Open(IRenderedComponent<TodoTaskPanel> cut,Guid id)=>cut.Find($"[data-testid='todo-recurring-{id:D}']").Click();
    private static void Confirm(IRenderedComponent<TodoTaskPanel> cut)=>cut.Find("[data-testid='todo-confirm']").Click();
    private static void Reload(IRenderedComponent<TodoTaskPanel> cut)=>cut.Find("[data-testid='recurring-reload']").Click();
    private static void Save(string name,string markup,string state,string test)=>Qualification.PageLayoutEvidence.Save(name,markup,"/tasks",state,["form","actions","confirmation","disabled-controls","error","navigation"],test);
    [Theory]
    [InlineData("Daily")][InlineData("Weekly")][InlineData("Monthly")]
    public async Task Complete_schedule_replacement_reviews_all_fields_and_preserves_independent_task_data(string frequency)
    {
        var task=Daily(new string('W',130)+" recurring work") with{Notes="Retain notes",Deadline=new(2026,11,1)};using var f=await Setup(new(){Id=Guid.NewGuid(),Revision=10,Tasks=[task]});var cut=Render<TodoTaskPanel>(p=>p.Add(x=>x.Kind,CompanionTaskKind.Daily));Open(cut,task.Id);var focusBeforeTyping=JSInterop.Invocations.Count(row=>row.Identifier=="Blazor._internal.domWrapper.focus");Assert.True(focusBeforeTyping>0);
        cut.Find("[data-testid='recurring-frequency']").Change(frequency);cut.Find("[data-testid='recurring-interval']").Change("2");cut.Find("[data-testid='recurring-start']").Change("2026-03-01");cut.Find("[data-testid='recurring-zone']").Change("Europe/Paris");
        if(frequency=="Weekly"){cut.Find("[data-testid='recurring-day-Monday']").Change(true);cut.Find("[data-testid='recurring-day-Friday']").Change(true);}if(frequency=="Monthly")cut.Find("[data-testid='recurring-month-days']").Change("1, 31");
        Assert.Equal(focusBeforeTyping,JSInterop.Invocations.Count(row=>row.Identifier=="Blazor._internal.domWrapper.focus"));Save("todo-recurring-"+frequency.ToLowerInvariant(),cut.Markup,"complete-"+frequency.ToLowerInvariant()+"-schedule-editor",nameof(Complete_schedule_replacement_reviews_all_fields_and_preserves_independent_task_data));cut.Find("[data-testid='recurring-editor'] form").Submit();var preview=f.Task.Controller.Preview!;Assert.Equal(WorkspaceOperation.UpdateTask,preview.Command.Operation);var rule=preview.Command.Patch!.Recurrence!;Assert.Equal(frequency,rule.Frequency.ToString());Assert.Equal(2,rule.Interval);Assert.Equal(new DateOnly(2026,3,1),rule.StartDate);Assert.Equal("Europe/Paris",rule.TimeZoneId);Assert.Equal(frequency=="Weekly"?2:0,rule.Weekdays.Count);Assert.Equal(frequency=="Monthly"?2:0,rule.DaysOfMonth.Count);Assert.Null(preview.Command.Patch.Text);Assert.Null(preview.Command.Patch.Notes);Assert.Null(preview.Command.Patch.Deadline);Assert.False(preview.MayAffectHabitica);Assert.Contains("Daily schedule",cut.Find("[data-testid='todo-review']").TextContent);Assert.Contains(task.Id.ToString(),cut.Find("[data-testid='todo-review']").TextContent);
        if(frequency=="Weekly")Save("todo-recurring-review",cut.Markup,"exact-full-schedule-replacement-review",nameof(Complete_schedule_replacement_reviews_all_fields_and_preserves_independent_task_data));Confirm(cut);var saved=f.Todo.Snapshot!.Document.Tasks.Single();Assert.Equal(rule,saved.Recurrence);Assert.Equal(task.Notes,saved.Notes);Assert.Equal(task.Deadline,saved.Deadline);Assert.Empty(f.Todo.Snapshot.Commands.Single().Effects);Assert.Empty(f.Todo.Snapshot.Document.Occurrences);Assert.Empty(f.Todo.Snapshot.Document.Completions);
    }
    [Fact]
    public async Task Invalid_rules_timezones_and_noop_replacement_fail_before_transport()
    {
        var task=Daily() with{Recurrence=Rule};using var f=await Setup(new(){Id=Guid.NewGuid(),Revision=10,Tasks=[task]});var cut=Render<TodoTaskPanel>(p=>p.Add(x=>x.Kind,CompanionTaskKind.Daily));Open(cut,task.Id);cut.Find("[data-testid='recurring-editor'] form").Submit();Assert.Contains("Change the schedule",cut.Markup);
        foreach(var interval in new[]{"0","","367","x"}){cut.Find("[data-testid='recurring-interval']").Change(interval);cut.Find("[data-testid='recurring-editor'] form").Submit();Assert.Contains("1 to 366",cut.Markup);}cut.Find("[data-testid='recurring-interval']").Change("1");cut.Find("[data-testid='recurring-start']").Change("");cut.Find("[data-testid='recurring-editor'] form").Submit();Assert.Contains("start date",cut.Markup);cut.Find("[data-testid='recurring-start']").Change("2026-03-01");cut.Find("[data-testid='recurring-frequency']").Change("Weekly");cut.Find("[data-testid='recurring-editor'] form").Submit();Assert.Contains("required weekdays",cut.Markup);cut.Find("[data-testid='recurring-day-Monday']").Change(true);cut.Find("[data-testid='recurring-zone']").Change("Unavailable/Zone");cut.Find("[data-testid='recurring-editor'] form").Submit();Assert.Contains("time zone is unavailable",cut.Markup);
        Save("todo-recurring-error",cut.Markup,"unsupported-zone-and-schedule-error",nameof(Invalid_rules_timezones_and_noop_replacement_fail_before_transport));cut.Find("[data-testid='recurring-zone']").Change("UTC");cut.Find("[data-testid='recurring-frequency']").Change("Monthly");foreach(var invalid in new[]{"1,1","0","32","","1,x"}){cut.Find("[data-testid='recurring-month-days']").Change(invalid);cut.Find("[data-testid='recurring-editor'] form").Submit();Assert.Contains("distinct month dates",cut.Markup);}Assert.Null(f.Task.Controller.Preview);Assert.Empty(f.Task.Client.PreparationIds);
    }
    [Fact]
    public async Task Dated_actions_pause_resume_and_clearing_retain_precedence_and_never_change_Habitica()
    {
        var task=Daily() with{Recurrence=Rule};var retainedOccurrence=new TaskOccurrence(Guid.NewGuid(),10,task.Id,new(2026,3,29),OccurrenceState.Completed);var retainedCompletion=new CompletionEvent(Guid.NewGuid(),10,task.Id,Guid.NewGuid(),Now,retainedOccurrence.Id);using var f=await Setup(new(){Id=Guid.NewGuid(),Revision=10,Tasks=[task],Occurrences=[retainedOccurrence],Completions=[retainedCompletion]});var cut=Render<TodoTaskPanel>(p=>p.Add(x=>x.Kind,CompanionTaskKind.Daily));Open(cut,task.Id);cut.FindAll("button").Single(b=>b.TextContent.Trim()=="Use current day in saved schedule zone").Click();Assert.Equal("2026-03-30",cut.Find("[data-testid='recurring-date']").GetAttribute("value"));Assert.Contains("Europe/Paris",cut.Find("[data-testid='recurring-occurrence-status']").TextContent);
        cut.Find("[data-testid='recurring-skip']").Click();Assert.Equal(WorkspaceOperation.SkipOccurrence,f.Task.Controller.Preview!.Command.Operation);Assert.Equal(new DateOnly(2026,3,30),f.Task.Controller.Preview.Command.OccurrenceDate);Save("todo-recurring-skip",cut.Markup,"exact-pending-date-skip-review",nameof(Dated_actions_pause_resume_and_clearing_retain_precedence_and_never_change_Habitica));Confirm(cut);Reload(cut);cut.Find("[data-testid='recurring-date']").Change("2026-03-30");Assert.Contains("Retained Skipped",cut.Markup);Assert.True(cut.Find("[data-testid='recurring-complete']").HasAttribute("disabled"));Assert.Single(f.Todo.Snapshot!.Document.Completions);
        Assert.Single(f.Todo.Snapshot!.Document.Completions);cut.Find("[data-testid='recurring-lifecycle']").Click();Assert.Contains("does not pause Habitica penalties",cut.Find("[data-testid='todo-review']").TextContent);Confirm(cut);Reload(cut);Assert.Equal(CompanionTaskState.Paused,f.Todo.Snapshot.Document.Tasks.Single().State);cut.Find("[data-testid='recurring-date']").Change("2026-03-31");Assert.True(cut.Find("[data-testid='recurring-complete']").HasAttribute("disabled"));Save("todo-recurring-paused",cut.Markup.Replace("<details class=\"recurring-history\">","<details class=\"recurring-history\" open>",StringComparison.Ordinal),"paused-native-task-and-retained-occurrence-history",nameof(Dated_actions_pause_resume_and_clearing_retain_precedence_and_never_change_Habitica));
        cut.Find("[data-testid='recurring-lifecycle']").Click();Assert.Equal(WorkspaceOperation.ResumeTask,f.Task.Controller.Preview!.Command.Operation);Confirm(cut);Reload(cut);cut.Find("[data-testid='recurring-clear']").Click();Assert.True(f.Task.Controller.Preview!.Command.Patch!.ClearRecurrence);Confirm(cut);Reload(cut);Assert.Null(f.Todo.Snapshot.Document.Tasks.Single().Recurrence);Assert.Equal(2,f.Todo.Snapshot.Document.Occurrences.Count);Assert.Single(f.Todo.Snapshot.Document.Completions);cut.Find("[data-testid='recurring-date']").Change("2026-03-30");Assert.Contains("Retained Skipped",cut.Markup);cut.Find("[data-testid='recurring-date']").Change("2026-03-31");Assert.False(cut.Find("[data-testid='recurring-complete']").HasAttribute("disabled"));Assert.True(cut.Find("[data-testid='recurring-skip']").HasAttribute("disabled"));Assert.All(f.Todo.Snapshot.Commands,entry=>Assert.Empty(entry.Effects));Assert.Empty(f.Todo.Snapshot.Document.HabitScores);Save("todo-recurring-unscheduled",cut.Markup.Replace("<details class=\"recurring-history\">","<details class=\"recurring-history\" open>",StringComparison.Ordinal),"explicit-unscheduled-completion-with-retained-history",nameof(Dated_actions_pause_resume_and_clearing_retain_precedence_and_never_change_Habitica));
    }
    [Theory][InlineData(false)][InlineData(true)]
    public async Task Lost_schedule_preview_or_acceptance_recovers_the_original_without_duplicate_history(bool cloud)
    {
        var task=Daily() with{Recurrence=Rule};using var f=await Setup(new(){Id=Guid.NewGuid(),Revision=10,Tasks=[task]},cloud);var cut=Render<TodoTaskPanel>(p=>p.Add(x=>x.Kind,CompanionTaskKind.Daily));Open(cut,task.Id);cut.Find("[data-testid='recurring-interval']").Change("2");if(cloud)f.Task.Client.LosePreparation=true;cut.Find("[data-testid='recurring-editor'] form").Submit();if(cloud){var request=Assert.Single(f.Task.Client.PreparationIds);cut.Find("[data-testid='todo-retry-preview']").Click();Assert.Equal(new[]{request,request},f.Task.Client.PreparationIds);}var id=f.Task.Controller.Preview!.PreparedCommandId;if(cloud)f.Task.Client.LoseAcceptance=true;else f.Task.Js.LoseCommitAcknowledgement=true;Confirm(cut);Assert.True(f.Task.Controller.AcceptanceUnknown);Assert.True(cut.Find("[data-testid='recurring-editor'] fieldset").HasAttribute("disabled"));if(cloud)Save("todo-recurring-unknown",cut.Markup,"original-schedule-acceptance-uncertainty",nameof(Lost_schedule_preview_or_acceptance_recovers_the_original_without_duplicate_history));cut.Find("[data-testid='todo-recover']").Click();Assert.Equal(id,f.Task.Controller.LastReceipt!.CommandId);Assert.Single(f.Todo.Snapshot!.Commands);Assert.Equal(2,f.Todo.Snapshot.Document.Tasks.Single().Recurrence!.Interval);Assert.Empty(f.Todo.Snapshot.Document.Completions);Assert.Empty(f.Todo.Snapshot.Document.Occurrences);if(cloud)Assert.Single(f.Task.Client.AcceptedIds);
    }
    [Theory][InlineData(false)][InlineData(true)]
    public async Task Retained_game_mappings_block_native_controls_before_preparation(bool archived)
    {
        var task=Daily() with{Recurrence=Rule};var mapping=new HabiticaProjection(Guid.NewGuid(),1,task.Id,ProjectionState.UnknownOutcome,"00000000-0000-4000-8000-000000000099",archived);using var f=await Setup(new(){Id=Guid.NewGuid(),Revision=10,Tasks=[task],Projections=[mapping]});var cut=Render<TodoTaskPanel>(p=>p.Add(x=>x.Kind,CompanionTaskKind.Daily));Open(cut,task.Id);Assert.True(cut.Find("[data-testid='recurring-editor'] fieldset").HasAttribute("disabled"));Assert.Contains("retained Habitica mapping",cut.Markup);await Assert.ThrowsAsync<InvalidOperationException>(()=>cut.Instance.ReviewRecurringAsync(new(f.Todo.Selection!,10,task.Id,WorkspaceOperation.PauseTask)));Assert.Empty(f.Task.Client.PreparationIds);Assert.Empty(f.Task.Client.AcceptedIds);cut.Find("[data-testid='recurring-date']").Change("2026-03-30");Assert.True(cut.Find("[data-testid='recurring-complete']").HasAttribute("disabled"));Assert.True(cut.Find("[data-testid='recurring-skip']").HasAttribute("disabled"));if(!archived)Save("todo-recurring-linked",cut.Markup,"game-linked-native-controls-unavailable",nameof(Retained_game_mappings_block_native_controls_before_preparation));await Assert.ThrowsAsync<InvalidOperationException>(()=>cut.Instance.ReviewRecurringAsync(new(f.Todo.Selection!,10,task.Id,WorkspaceOperation.CompleteTask,OccurrenceDate:new(2026,3,30))));Assert.Empty(f.Task.Client.PreparationIds);Assert.Equal(mapping,f.Todo.Snapshot!.Document.Projections.Single());
    }
    [Fact]
    public async Task Stale_context_requires_reload_and_account_change_discards_private_editor()
    {
        var task=Daily("Private schedule") with{Recurrence=Rule};using var f=await Setup(new(){Id=Guid.NewGuid(),Revision=10,Tasks=[task]});var cut=Render<TodoTaskPanel>(p=>p.Add(x=>x.Kind,CompanionTaskKind.Daily));Open(cut,task.Id);cut.Find("[data-testid='recurring-zone']").Change("America/New_York");f.Task.Client.State=f.Task.Client.State with{Document=f.Task.Client.State.Document with{Revision=11},StoreVersion=11};await f.Todo.LoadSelectedAsync();Assert.True(cut.Find("[data-testid='recurring-editor'] fieldset").HasAttribute("disabled"));cut.Find("[data-testid='recurring-editor'] form").Submit();Assert.Null(f.Task.Controller.Preview);Assert.Empty(f.Task.Client.PreparationIds);Reload(cut);Assert.Equal("Europe/Paris",cut.Find("[data-testid='recurring-zone']").GetAttribute("value"));f.Task.Session.SetState(f.Task.Session.State with{UserId="00000000-0000-4000-8000-000000000012"});cut.WaitForAssertion(()=>Assert.Empty(cut.FindAll("[data-testid='recurring-editor']")));Assert.DoesNotContain("Private schedule",cut.Markup);
    }
    [Fact]
    public async Task History_is_paged_and_unavailable_zone_does_not_fabricate_due_state()
    {
        var task=Daily() with{Recurrence=Rule with{TimeZoneId="Unavailable/Zone"}};var rows=Enumerable.Range(0,25).Select(i=>new TaskOccurrence(Guid.NewGuid(),1,task.Id,new DateOnly(2026,1,1).AddDays(i),OccurrenceState.Skipped)).ToArray();using var f=await Setup(new(){Id=Guid.NewGuid(),Revision=10,Tasks=[task],Occurrences=rows});var cut=Render<TodoTaskPanel>(p=>p.Add(x=>x.Kind,CompanionTaskKind.Daily));Open(cut,task.Id);Assert.Equal(20,cut.FindAll(".recurring-history li").Count);cut.FindAll(".recurring-history button").Single(b=>b.TextContent.Trim()=="Next records").Click();Assert.Equal(5,cut.FindAll(".recurring-history li").Count);cut.Find("[data-testid='recurring-date']").Change("2026-03-30");Assert.Contains("No due state is inferred",cut.Markup);Assert.True(cut.Find("[data-testid='recurring-complete']").HasAttribute("disabled"));Assert.True(cut.Find("[data-testid='recurring-skip']").HasAttribute("disabled"));cut.FindAll("button").Single(b=>b.TextContent.Trim()=="Use current day in saved schedule zone").Click();Assert.Contains("Select a civil date explicitly",cut.Markup);Assert.Empty(f.Task.Client.PreparationIds);Save("todo-recurring-unavailable",cut.Markup.Replace("<details class=\"recurring-history\">","<details class=\"recurring-history\" open>",StringComparison.Ordinal),"unknown-zone-and-paged-retained-dates",nameof(History_is_paged_and_unavailable_zone_does_not_fabricate_due_state));
    }
    [Fact]
    public async Task Typed_creation_transmits_recurrence_and_invalid_or_unsupported_rules_are_refused_locally()
    {
        var f=new WorkspaceTaskFixture();await f.Controller.CreateLocalAsync();var supported=Rule with{TimeZoneId="UTC"};var input=WorkspaceTaskFixture.Todo() with{Operation=WorkspaceOperation.CreateDaily,Recurrence=supported};await f.Controller.PrepareAsync(input);Assert.Equal(supported,f.Controller.Preview!.Command.Patch!.Recurrence);await f.Controller.ConfirmAsync();var saved=f.Controller.Snapshot!.Document.Tasks.Single().Recurrence!;Assert.Equal(Rule.Frequency,saved.Frequency);Assert.Equal(Rule.Interval,saved.Interval);Assert.Equal(Rule.StartDate,saved.StartDate);Assert.Equal(supported.TimeZoneId,saved.TimeZoneId);Assert.Empty(saved.Weekdays);Assert.Empty(saved.DaysOfMonth);Assert.Equal(new[]{ProjectionEffectKind.Create},f.Controller.Snapshot.Commands.Single().Effects);
        foreach(var bad in new[]{input with{Recurrence=Rule with{TimeZoneId="Unavailable/Zone"}},input with{Operation=WorkspaceOperation.CreateTodo},input with{ClearRecurrence=true}}){await Assert.ThrowsAsync<InvalidOperationException>(()=>f.Controller.PrepareAsync(bad));Assert.Null(f.Controller.Preview);Assert.False(f.Controller.HasPendingIntent);}Assert.Single(f.Controller.Snapshot.Commands);
    }
    [Theory][InlineData(false)][InlineData(true)]
    public async Task Non_due_weekly_and_monthly_dates_cannot_be_completed_or_skipped(bool monthly)
    {
        var task=Daily() with{Recurrence=monthly?new(RecurrenceFrequency.Monthly,1,new(2026,1,1),"UTC",[],[31]):new(RecurrenceFrequency.Weekly,1,new(2026,3,2),"UTC",[DayOfWeek.Monday],[])};using var f=await Setup(new(){Id=Guid.NewGuid(),Revision=10,Tasks=[task]});var cut=Render<TodoTaskPanel>(p=>p.Add(x=>x.Kind,CompanionTaskKind.Daily));Open(cut,task.Id);cut.Find("[data-testid='recurring-date']").Change(monthly?"2026-02-28":"2026-03-03");Assert.Contains("Not scheduled",cut.Markup);Assert.True(cut.Find("[data-testid='recurring-complete']").HasAttribute("disabled"));Assert.True(cut.Find("[data-testid='recurring-skip']").HasAttribute("disabled"));await Assert.ThrowsAsync<InvalidOperationException>(()=>cut.Instance.ReviewRecurringAsync(new(f.Todo.Selection!,10,task.Id,WorkspaceOperation.CompleteTask,OccurrenceDate:monthly?new(2026,2,28):new(2026,3,3))));Assert.Empty(f.Task.Client.PreparationIds);cut.Find("[data-testid='recurring-date']").Change(monthly?"2026-03-31":"2026-03-09");Assert.False(cut.Find("[data-testid='recurring-skip']").HasAttribute("disabled"));
    }
    [Fact]
    public async Task Native_Habit_pause_retains_scores_without_exposing_Daily_schedule_fields()
    {
        var task=Daily("Habit") with{Kind=CompanionTaskKind.Habit};using var f=await Setup(new(){Id=Guid.NewGuid(),Revision=10,Tasks=[task]});var cut=Render<TodoTaskPanel>(p=>p.Add(x=>x.Kind,CompanionTaskKind.Habit));Open(cut,task.Id);Assert.Empty(cut.FindAll("[data-testid='recurring-frequency']"));cut.Find("[data-testid='recurring-lifecycle']").Click();Confirm(cut);Reload(cut);Assert.Equal(CompanionTaskState.Paused,f.Todo.Snapshot!.Document.Tasks.Single().State);Assert.Empty(f.Todo.Snapshot.Document.HabitScores);Assert.Empty(f.Todo.Snapshot.Commands.Single().Effects);Save("todo-recurring-habit",cut.Markup,"native-habit-pause-without-recurrence-conversion",nameof(Native_Habit_pause_retains_scores_without_exposing_Daily_schedule_fields));
    }
}
